document.addEventListener('DOMContentLoaded',()=>{const box=document.querySelector('.mapbox');if(!box)return;box.innerHTML='<strong>MAPA DE ANGRA DOS REIS</strong><div class="real-map"><iframe title="Mapa real de Angra dos Reis" loading="lazy" src="https://www.openstreetmap.org/export/embed.html?bbox=-44.55%2C-23.25%2C-44.00%2C-22.85&layer=mapnik&marker=-23.006%2C-44.318"></iframe></div><small>Destino atual: <b>Praia do Aventureiro</b></small>';const s=document.createElement('style');s.textContent='.real-map{height:235px;margin:12px 0;border-radius:16px;overflow:hidden;background:#cfe5e3}.real-map iframe{width:100%;height:100%;border:0;display:block}';document.head.appendChild(s)});
